def select_demand(corpus_df):
    fallback_ids = ['n06-r07', 'n06-r08']
    evidence_fields = ['jobs', 'pain', 'triggers', 'alternatives', 'consequences', 'outcomes']
    records = []

    score_mask = corpus_df.get('demand_score', 0) >= 3
    fallback_mask = corpus_df.get('record_id', '').isin(fallback_ids)
    selected_df = corpus_df[score_mask | fallback_mask]

    available_evidence_fields = [field for field in evidence_fields if field in selected_df.columns]
    if available_evidence_fields:
        evidence_mask = selected_df[available_evidence_fields].fillna('').astype(str).apply(
            lambda row: any(value.strip() for value in row), axis=1
        )
        selected_df = selected_df[evidence_mask | selected_df.get('record_id', '').isin(fallback_ids)]

    for _, row in selected_df.iterrows():
        records.append({'record_id': row.get('record_id', ''), 'need': row.get('need', ''), 'demand_score': row.get('demand_score', 0), 'source_id': row.get('source_id', ''), 'source_weight': row.get('source_weight', 0)})
    return pd.DataFrame(records)
